'use strict';
(function(){let dialog,video,cover,status;const base='videos/2026-11-19/fragment-guide-20261119-silero-kseniya-v1';
function openTutorial(){if(!dialog){dialog=document.createElement('dialog');dialog.className='tutorial-video-dialog';dialog.setAttribute('aria-label','Видеоинструкция — Фрагмент');dialog.innerHTML='<div class="tutorial-head"><strong>Видеоинструкция — Фрагмент</strong><button type="button" aria-label="Закрыть видеоинструкцию">Закрыть</button></div><div class="tutorial-player"><video controls playsinline preload="metadata" poster="'+base+'-poster.jpg"><source src="'+base+'.mp4" type="video/mp4"><track kind="subtitles" src="'+base+'.vtt" srclang="ru" label="Русские субтитры" default></video><div class="tutorial-cover"><img src="'+base+'-poster.jpg" alt="Заставка видеоинструкции"><button type="button" aria-label="Смотреть видео со звуком">▶</button><span role="status">Нажмите ▶ для запуска</span></div></div><div class="tutorial-links"><a href="'+base+'.mp4" target="_blank" rel="noopener">Открыть MP4 отдельно</a><a href="instruction-20261119.html" target="_blank" rel="noopener">Страница инструкции и субтитры</a></div>';document.body.append(dialog);video=dialog.querySelector('video');cover=dialog.querySelector('.tutorial-cover');status=cover.querySelector('span');const play=()=>{video.scrollIntoView({block:'nearest'});video.muted=false;video.volume=1;status.textContent='Загрузка видео…';video.play().catch(()=>status.textContent='Нажмите ▶ для запуска со звуком')};dialog.querySelector('.tutorial-head button').onclick=()=>dialog.close();cover.querySelector('button').onclick=play;video.onplaying=()=>cover.hidden=true;video.onended=()=>{cover.hidden=false;status.textContent='Посмотреть ещё раз'};video.onerror=()=>{cover.hidden=false;status.textContent='Не удалось загрузить видео. Откройте MP4 по ссылке ниже.'};dialog.addEventListener('close',()=>video.pause());dialog.playTutorial=play}if(!dialog.open)dialog.showModal();dialog.playTutorial()}
const style=document.createElement('style');style.textContent='.tutorial-video-dialog{width:min(1100px,94vw,calc(177.78dvh - 248.9px));max-width:94vw;max-height:94dvh;padding:12px;border:1px solid #425965;border-radius:12px;background:#111b23;color:#f4f8fa}.tutorial-video-dialog::backdrop{background:#000b}.tutorial-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:10px}.tutorial-head strong{font-size:16px}.tutorial-head button,.tutorial-cover button{background:#70edbb;color:#10251d;border:0;border-radius:8px;padding:9px 12px}.tutorial-player{position:relative;aspect-ratio:16/9}.tutorial-player video::cue{font-size:clamp(7px,1.1vw,20px);color:white;background:#111b23e8}.tutorial-player video{display:block;width:100%;height:100%;background:#111b23}.tutorial-cover{position:absolute;inset:0;display:grid;place-items:center;background:#111b23}.tutorial-cover[hidden]{display:none}.tutorial-cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}.tutorial-cover button{position:relative;font-size:38px;min-width:75px;min-height:75px;border-radius:50%}.tutorial-cover span{position:absolute;bottom:5px;background:#111b23e8;padding:3px 9px;font-size:13px}.tutorial-links{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;font-size:14px}.tutorial-links a{color:#70edbb}.tutorial-video-dialog button:focus-visible{outline:3px solid white;outline-offset:3px}';document.head.append(style);document.getElementById('videos').onclick=openTutorial;
})();
